#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char s[100];
    int i, v = 0, c = 0, d = 0, sp = 0;

    printf("Enter a line: ");
    fgets(s, sizeof(s), stdin);

    for (i = 0; s[i] != '\0'; i++)
    {
        char ch = tolower(s[i]);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u')
            v++;
        else if (isalpha(ch))
            c++;
        else if (isdigit(ch))
            d++;
        else if (ch == ' ')
            sp++;
    }
    printf("Vowels = %d, Consonants = %d, Digits = %d, Spaces = %d\n", v, c, d, sp);
    return 0;
}

