#include <stdio.h>
#include <string.h>

int main(void)
{
    char s[50], r[50];
    int i, n;

    printf("Enter a string: ");
    scanf("%49s", s);

    n = strlen(s);
    for (i = 0; i < n; i++)
        // last char first
        r[i] = s[n - 1 - i];
    // terminate the copy
    r[n] = '\0';

    printf("Reverse = %s\n", r);
    if (strcmp(s, r) == 0)
        printf("%s is a PALINDROME\n", s);
    else
        printf("%s is NOT a palindrome\n", s);
    return 0;
}

#include <stdio.h>

int my_strlen(char s[]);
void my_strcpy(char d[], char s[]);
void my_strcat(char d[], char s[]);

int main(void)
{
    char a[40], b[] = "Engineering";

    my_strcpy(a, "Computer ");
    printf("After copy : %s\n", a);
    my_strcat(a, b);
    printf("After join : %s\n", a);
    printf("Length     : %d\n", my_strlen(a));
    return 0;
}

int my_strlen(char s[])
{
    int i = 0;
    while (s[i] != '\0')
        i++;
    return i;
}

void my_strcpy(char d[], char s[])
{
    int i = 0;
    // copy including '\0'
    while ((d[i] = s[i]) != '\0')
        i++;
}

void my_strcat(char d[], char s[])
{
    // start at end of d
    int i = my_strlen(d), j = 0;
    while (s[j] != '\0')
        d[i++] = s[j++];
    d[i] = '\0';
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char s[100];
    int i, words = 0, inword = 0;

    printf("Enter a sentence: ");
    fgets(s, sizeof(s), stdin);

    for (i = 0; s[i] != '\0'; i++)
    {
        if (isspace(s[i]))
            inword = 0;
        // start of a new word
        else if (!inword)
        {
            inword = 1;
            words++;
        }
    }

    printf("Upper  : ");
    for (i = 0; s[i] != '\0'; i++) putchar(toupper(s[i]));
    printf("Lower  : ");
    for (i = 0; s[i] != '\0'; i++) putchar(tolower(s[i]));
    printf("Toggle : ");
    for (i = 0; s[i] != '\0'; i++)
        putchar(isupper(s[i]) ? tolower(s[i]) : toupper(s[i]));
    printf("Words  = %d\n", words);
    return 0;
}

#include <stdio.h>
#include <string.h>

int main(void)
{
    char name[10][20], temp[20];
    int n, i, j;

    printf("How many names? ");
    scanf("%d", &n);
    printf("Enter %d names:\n", n);
    for (i = 0; i < n; i++)
        // name[i] is a row (string)
        scanf("%19s", name[i]);

    // bubble sort on strings
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (strcmp(name[j], name[j + 1]) > 0)
            {
                strcpy(temp, name[j]);
                strcpy(name[j], name[j + 1]);
                strcpy(name[j + 1], temp);
            }

    printf("Sorted names:\n");
    for (i = 0; i < n; i++)
        printf("%d. %s\n", i + 1, name[i]);
    return 0;
}

