int main(void)
{
    FILE *fp;
    int ch, chars = 0, words = 0, lines = 0, inword = 0;

    fp = fopen("poem.txt", "r");
    if (fp == NULL)
    {
        printf("File not found\n");
        return 1;
    }

    // read till end of file
    while ((ch = fgetc(fp)) != EOF)
    {
        // display the file
        putchar(ch);
        chars++;
        if (ch == '\n')
            lines++;
        if (isspace(ch))
            inword = 0;
        else if (!inword)
        {
            inword = 1;
            words++;
        }
    }
    fclose(fp);

    printf("Characters = %d, Words = %d, Lines = %d\n", chars, words, lines);
    return 0;
}

#include <stdio.h>

int main(int argc, char *argv[])
{
    FILE *fs, *ft;
    int ch;

    if (argc != 3)
    {
        printf("Usage: %s source target\n", argv[0]);
        return 1;
    }
    fs = fopen(argv[1], "r");
    if (fs == NULL)
    {
        printf("Cannot open %s\n", argv[1]);
        return 1;
    }
    ft = fopen(argv[2], "w");
    if (ft == NULL)
    {
        printf("Cannot create %s\n", argv[2]);
        fclose(fs);
        return 1;
    }

    // copy char by char
    while ((ch = fgetc(fs)) != EOF)
        fputc(ch, ft);
    fclose(fs);
    fclose(ft);
    printf("%s copied to %s\n", argv[1], argv[2]);

    // show the copy
    ft = fopen(argv[2], "r");
    printf("--- %s ---\n", argv[2]);
    while ((ch = fgetc(ft)) != EOF)
        putchar(ch);
    fclose(ft);
    return 0;
}

