#include <stdio.h>
#include <string.h>

void replace(char *line, char *find, char *rep, char *out);

int main(void)
{
    FILE *fin, *fout;
    char line[200], out[400], find[30], rep[30];
    int count = 0;

    printf("Word to find   : ");
    scanf("%29s", find);
    printf("Replace with   : ");
    scanf("%29s", rep);

    fin = fopen("story.txt", "r");
    fout = fopen("result.txt", "w");
    if (fin == NULL || fout == NULL)
    {
        printf("File error\n");
        return 1;
    }
    while (fgets(line, sizeof(line), fin) != NULL)
    {
        if (strstr(line, find) != NULL)
            count++;
        replace(line, find, rep, out);
        fputs(out, fout);
    }
    fclose(fin);
    fclose(fout);
    printf("Lines changed  : %d\n--- result.txt ---\n", count);

    fin = fopen("result.txt", "r");
    while (fgets(line, sizeof(line), fin) != NULL)
        printf("%s", line);
    fclose(fin);
    return 0;
}

void replace(char *line, char *find, char *rep, char *out)
{
    char *p = line, *q;
    int fl = strlen(find);

    out[0] = '\0';
    // next occurrence
    while ((q = strstr(p, find)) != NULL)
    {
        // text before word
        strncat(out, p, q - p);
        // new word
        strcat(out, rep);
        // skip old word
        p = q + fl;
    }
    // rest of line
    strcat(out, p);
}

